    {"symbol": "🧮", "tooltip": "Externality accounting is like a missing ledger entry; it makes a profitable trade look unprofitable once the off-book costs are recorded"},
    {"symbol": "🪤", "tooltip": "Auditor-auditee dependence is like a snare; it springs precisely when independent verification was supposed to save you"}
  ],
  "claim_sketches": [
    {"claim": "The relevant base rate for AI-authored consumer code is the incident history of supply-chain compromises and slopsquatting attacks, not generic startup mortality or enterprise AI failure.", "targets": []},
    {"claim": "Agentic test coverage at 5% overhead depends on an undefended premise: that the AI verifying the code does not share the failure distribution of the AI writing it.", "targets": []},
    {"claim": "Comprehensibility is human oversight capacity, and oversight capacity is the binding constraint when a consumer product has a 3 a.m. incident — 'ask the AI to explain its own code' is using the failing system to diagnose itself.", "targets": []},
    {"claim": "Pre-deployment hazard verification for a 90-day MVP is a bounded enumerated checklist — dependency provenance, secret scanning, known-CVE gates, named human signoff — not a SOC2 regime, and the cost is dominated by week-one setup.", "targets": []},
    {"claim": "Agency costs run symmetrically: if engineers inflate rewrite probability, Product and Finance deflate costs that surface after the bonus cycle, and only externally-visible hazard thresholds break the tie.", "targets": []},
    {"claim": "Customer-validation kill criteria fire after users have absorbed the harm; a supply-chain compromise during the validation window is not undone by killing the product on day 90.", "targets": []}
  ],
  "key_assumptions": [
    {"assumption": "AI-authored code has materially different failure modes — particularly hallucinated dependencies and reward-hacked test suites — than human-authored code at the same nominal defect rate.", "if_wrong": "If AI-specific failure modes turn out to be statistically indistinguishable from generic defects, the case for AI-specific pre-deployment verification collapses into ordinary code-quality practice, and Accelerationist's framing of safety-as-tax becomes defensible at MVP scale."},
    {"assumption": "Human comprehension of the codebase is the binding constraint for incident response in consumer software, and AI-assisted explanation of AI-generated code does not substitute for it under incident conditions.", "if_wrong": "If AI-assisted incident response proves reliable out-of-distribution, the comprehensibility-decay argument weakens substantially, and the case shifts to supply-chain and reward-hacking grounds alone."}
  ]
